package com.orderflow.orchestrator; import com.orderflow.contracts.*; import org.springframework.kafka.annotation.KafkaListener; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.stereotype.Component; import java.time.Instant; import java.util.UUID;
@Component public class SagaOrchestrator { private final KafkaTemplate<String,Object> kafka; public SagaOrchestrator(KafkaTemplate<String,Object> k){kafka=k;}
 private SagaEvent next(SagaEvent e,SagaStep src,SagaStatus status,String msg){return new SagaEvent(UUID.randomUUID().toString(),e.transactionId(),e.orderId(),src,status,msg,e.payload(),Instant.now());}
 @KafkaListener(topics=Topics.START,groupId="orchestrator-start") public void start(SagaEvent e){kafka.send(Topics.PRODUCT,e.orderId(),next(e,SagaStep.ORCHESTRATOR,SagaStatus.STARTED,"Validate products"));}
 @KafkaListener(topics=Topics.ORCHESTRATOR,groupId="orchestrator-results") public void result(SagaEvent e){ if(e.source()==SagaStep.PRODUCT_VALIDATION){ if(e.status()==SagaStatus.SUCCESS) kafka.send(Topics.PAYMENT,e.orderId(),next(e,SagaStep.ORCHESTRATOR,SagaStatus.STARTED,"Process payment")); else finish(e,"Product validation failed"); } else if(e.source()==SagaStep.PAYMENT){ if(e.status()==SagaStatus.SUCCESS) kafka.send(Topics.INVENTORY,e.orderId(),next(e,SagaStep.ORCHESTRATOR,SagaStatus.STARTED,"Reserve inventory")); else finish(e,"Payment failed"); } else if(e.source()==SagaStep.INVENTORY){ if(e.status()==SagaStatus.SUCCESS) complete(e); else { kafka.send(Topics.PAYMENT,e.orderId(),next(e,SagaStep.ORCHESTRATOR,SagaStatus.ROLLBACK,"Refund payment")); finish(e,"Inventory failed; compensation requested"); } } }
 private void complete(SagaEvent e){kafka.send(Topics.ORDER_NOTIFY,e.orderId(),next(e,SagaStep.ORCHESTRATOR,SagaStatus.FINISHED,"Saga finished successfully"));}
 private void finish(SagaEvent e,String m){kafka.send(Topics.ORDER_NOTIFY,e.orderId(),next(e,SagaStep.ORCHESTRATOR,SagaStatus.FAILED,m));}
}
